def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for c in range(w):
        if 0 < c < w - 1 and w - c - 1 == c and len({row[c] for row in grid}) == 1:
            split = ("v", c)
            break
    if split is None:
        for r in range(h):
            if 0 < r < h - 1 and h - r - 1 == r and len(set(grid[r])) == 1:
                split = ("h", r)
                break
    if split is None:
        raise ValueError("No centered uniform divider found")
    axis, k = split
    if axis == "v":
        left = [row[:k] for row in grid]
        right = [row[k + 1:] for row in grid]
    else:
        left = grid[:k]
        right = grid[k + 1:]
    shared = set(map(tuple, left)) if axis == "h" else set()
    if axis == "v":
        a = {x for row in left for x in row}
        b = {x for row in right for x in row}
    else:
        a = {x for row in left for x in row}
        b = {x for row in right for x in row}
    common = a & b
    mismatch = next(iter(common))
    if axis == "v":
        return [[3 if left[r][c] == right[r][c] else mismatch for c in range(k)] for r in range(h)]
    return [[3 if left[r][c] == right[r][c] else mismatch for c in range(w)] for r in range(k)]
